"use client";
import React, { memo } from "react";

import type { DialogConfig } from "@/registry/new-york/dialog-manager/DialogManager";
import type { SimpleDialogProps } from "@/registry/new-york/simple-dialog/SimpleDialog";
import { SimpleDialog } from "@/registry/new-york/simple-dialog/SimpleDialog";

const isIntrinsicComponent = (
  component: React.ElementType
): component is keyof React.JSX.IntrinsicElements =>
  typeof component === "string";

const DialogListRender = ({
  dialogs,
  onClose,
  onRemove,
  defaultMobileView,
}: {
  dialogs: DialogConfig[];
  onClose: (id: string) => void;
  onRemove: (id: string) => void;
  defaultMobileView?: SimpleDialogProps["mobileView"] | undefined;
}) => (
  <>
    {dialogs.map(
      ({
        id,
        open,
        title,
        component: Component,
        props,
        size,
        classNames,
        mobileView,
        drawerTitle,
        showCancel,
        showCloseButton,
        onCancel,
        onSubmit,
        submitText,
        cancelText,
      }) => (
        <div key={id} className="pointer-events-auto">
          <SimpleDialog
            title={title}
            open={open}
            onOpenChangeComplete={(next) => {
              if (!next) {
                onRemove(id);
              }
            }}
            onOpenChange={(nextOpen: boolean) => {
              if (!nextOpen) {
                onClose(id);
              }
            }}
            size={size}
            classNames={classNames}
            mobileView={mobileView ?? defaultMobileView}
            drawerTitle={drawerTitle}
            showCancel={showCancel}
            showCloseButton={showCloseButton}
            onCancel={() => {
              if (onCancel) {
                onCancel();
              }
              onClose(id);
            }}
            {...(onSubmit && {
              onSubmit: () => {
                onSubmit();
                onClose(id);
              },
            })}
            submitText={submitText}
            cancelText={cancelText}
          >
            {isIntrinsicComponent(Component) ? (
              <Component {...props} />
            ) : (
              <Component {...props} close={() => onClose(id)} />
            )}
          </SimpleDialog>
        </div>
      )
    )}
  </>
);
export const DialogList = memo(DialogListRender);

"use client";

import React, {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useState,
  memo,
} from "react";

import { cn } from "@/lib/utils";
import { DialogList } from "@/registry/new-york/dialog-manager/DialogList";
import type { SimpleDialogProps } from "@/registry/new-york/simple-dialog/SimpleDialog";

export interface OpenDialogProps<TProps extends object = object> {
  title?: string | undefined;
  component: React.ElementType;
  props?: TProps | undefined;
  size?: SimpleDialogProps["size"] | undefined;
  classNames?: SimpleDialogProps["classNames"] | undefined;
  mobileView?: SimpleDialogProps["mobileView"] | undefined;
  drawerTitle?: SimpleDialogProps["drawerTitle"] | undefined;
  showCancel?: SimpleDialogProps["showCancel"] | undefined;
  showCloseButton?: SimpleDialogProps["showCloseButton"] | undefined;
  onCancel?: SimpleDialogProps["onCancel"] | undefined;
  onSubmit?: SimpleDialogProps["onSubmit"] | undefined;
  submitText?: SimpleDialogProps["submitText"] | undefined;
  cancelText?: SimpleDialogProps["cancelText"] | undefined;
}
export type DialogConfig = OpenDialogProps & {
  id: string;
  open: boolean;
};
interface DialogContextType {
  openDialog: <TProps extends object>(
    config: OpenDialogProps<TProps>
  ) => string;
  closeDialog: (id: string) => void;
  closeAllDialogs: () => void;
}
const DialogContext = createContext<DialogContextType | null>(null);
export const useDialog = () => {
  const context = useContext(DialogContext);
  if (!context) {
    throw new Error("useDialog must be used within a DialogProvider");
  }
  return context;
};
export interface DialogManagerProps {
  classNames?:
    | {
        root?: string | undefined;
      }
    | undefined;
  mobileView?: SimpleDialogProps["mobileView"] | undefined;
  children?: React.ReactNode | undefined;
}
const DialogManagerRender = ({
  classNames,
  mobileView = "bottom-drawer",
  children,
}: DialogManagerProps) => {
  const [dialogs, setDialogs] = useState<DialogConfig[]>([]);
  const openDialog = useCallback((config: OpenDialogProps) => {
    const id = Math.random().toString(36).slice(7);
    setDialogs((prev) => {
      const newDialogs = [
        ...prev,
        {
          ...config,
          id,
          open: true,
        },
      ];
      return newDialogs;
    });
    return id;
  }, []);
  const closeDialog = useCallback((id: string) => {
    setDialogs((prev) =>
      prev.map((dialog) =>
        dialog.id === id ? { ...dialog, open: false } : dialog
      )
    );
  }, []);
  const closeAllDialogs = useCallback(() => {
    setDialogs((prev) => prev.map((dialog) => ({ ...dialog, open: false })));
  }, []);
  const contextValue = useMemo(
    () => ({
      closeAllDialogs,
      closeDialog,
      openDialog,
    }),
    [openDialog, closeDialog, closeAllDialogs]
  );
  return (
    <DialogContext.Provider value={contextValue}>
      {children}
      <div
        className={cn(
          "pointer-events-none fixed inset-0 z-[100]",
          classNames?.root
        )}
      >
        <DialogList
          dialogs={dialogs}
          onClose={closeDialog}
          onRemove={(id) =>
            setDialogs((prev) => prev.filter((dialog) => dialog.id !== id))
          }
          defaultMobileView={mobileView}
        />
      </div>
    </DialogContext.Provider>
  );
};
export const DialogManager = memo(DialogManagerRender);

import type { LucideIcon } from "lucide-react";
import type { PropsWithChildren } from "react";

export type ReactFC<T> = React.FC<PropsWithChildren & T>;
export type Size = "xs" | "sm" | "md" | "lg" | "xl";
export interface SelectOption {
  value: string;
  label?: string | undefined;
  emoji?: string | undefined;
  icon?: LucideIcon | undefined;
  closeOnClick?: boolean | undefined;
  disabled?: boolean | undefined;
}
